shaders.main:
#version 300 es
// Side Rays, from React Bits by David Haz (https://reactbits.dev, MIT +
// Commons Clause), used in Videorc with the author's permission. Adapted for
// Videorc (plan 190): mouse follow and the intro reveal are constants, dark
// mode only, drawn opaque over the look's base colour, and uniforms are packed
// into `u` (layout in live_background/mod.rs).
precision highp float;

uniform vec4 u[9];
out vec4 outColor;

float sq(float x) {
  return x * x;
}

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  vec2 w = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

float shafts(float x, float t, float seed, float aa) {
  float sway = (0.4 * sin(t * 0.31 + seed) + 0.24 * sin(t * 0.17 + seed * 2.3)) * u[7].w;
  float n = 0.7 * noise(vec2(x + sway + seed, t * 0.3)) + 0.3 * noise(vec2(x * 2.4 + sway * 1.5 + seed * 1.7, t * 0.45 + 3.0));
  float width = mix(0.5, 0.1, u[4].z);
  float s = mix(smoothstep(0.5 - width, 0.5 + width, n), 0.5, aa);
  return mix(0.05, 1.0, s);
}

float motes(vec2 p, float cell, float t, float seed) {
  p += vec2(t * 0.021, -t * 0.013) + seed * 7.31;
  vec2 grid = p / cell;
  vec2 id = floor(grid);
  vec2 f = grid - id;
  float h = hash(id + seed);
  if (h > 0.5) return 0.0;
  vec2 center = 0.25 + 0.5 * vec2(hash(id + 1.7 + seed), hash(id + 3.1 + seed));
  center += 0.1 * vec2(sin(t * 0.7 + h * 31.0), cos(t * 0.6 + h * 23.0));
  float size = mix(0.035, 0.09, hash(id + 5.3 + seed));
  float edge = length(fwidth(grid)) * 0.7;
  float twinkle = 0.55 + 0.45 * sin(t * 1.9 + h * 41.0);
  return (1.0 - smoothstep(size - edge, size + edge, length(f - center))) * twinkle;
}

void main() {
  vec2 res = u[0].xy;
  float aspect = res.x / res.y;
  vec2 q = (gl_FragCoord.xy - 0.5 * res) / res.y;
  if (u[6].x > 0.5) q.x = -q.x;
  if (u[6].y > 0.5) q.y = -q.y;
  vec2 source = u[6].z > 0.5 ? vec2(aspect * 0.5 + 0.42, 0.3) : vec2(aspect * 0.5 + 0.1, 0.62);
  float t = u[0].z;
  float swayAmount = u[7].w;
  float heading = (u[6].z > 0.5 ? 3.42 : -2.48) + u[6].w + 0.035 * sin(t * 0.21) * swayAmount;
  vec2 v = q - source;
  float r = length(v);
  float angle = mod(atan(v.y, v.x) - heading + 3.14159265, 6.28318531) - 3.14159265;
  float spread = u[4].x;
  float x = angle * u[4].y;
  float aa = smoothstep(0.12, 0.45, fwidth(x));
  float offset = spread * 0.22;
  float fanA = exp(-sq((angle + offset) / spread) * 1.4);
  float fanB = exp(-sq((angle - offset) / (spread * 1.15)) * 1.4);
  float focus = 1.0 + u[7].z * exp(-sq((angle - u[7].x) / u[7].y));
  float lightA = fanA * shafts(x, t, 0.0, aa) * focus;
  float lightB = fanB * shafts(x * 0.83, t * 0.6, 17.0, aa) * focus;
  float reach = 1.0 / (1.0 + pow(r / 0.4, u[4].w));
  float blend = u[2].w;
  vec3 colorA = u[2].rgb;
  vec3 colorB = u[3].rgb;
  vec3 glowColor = mix(colorA, colorB, blend);
  vec3 light = (colorA * lightA * (1.0 - blend) + colorB * lightB * blend) * 2.0 * reach;
  light += glowColor * u[5].x * exp(-sq(r / 0.4));
  float dust = u[5].z;
  if (dust > 0.0) {
    float sparkle = motes(q, 0.06, t, 0.0) + 0.7 * motes(q, 0.038, t * 0.8, 9.0);
    light += mix(glowColor, vec3(1.0), 0.6) * sparkle * (lightA + lightB) * reach * dust * 2.5;
  }
  // The intro reveal is finished (React Bits' uReveal = 1).
  light *= u[3].w * (1.0 - smoothstep(2.15, 2.6, r));
  float gray = dot(light, vec3(0.2126, 0.7152, 0.0722));
  light = max(mix(vec3(gray), light, u[5].y), 0.0);
  float peak = max(light.r, max(light.g, light.b));
  float grain = (fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0;
  float mapped = 1.0 - exp(-peak);
  vec3 tone = light * (mapped / max(peak, 1e-4));
  tone = mix(tone, vec3(mapped), smoothstep(0.7, 1.0, mapped) * 0.55);
  vec3 shown = clamp(tone * u[5].w, 0.0, 1.0);
  float alpha = max(shown.r, max(shown.g, shown.b));
  vec3 color = clamp(shown * alpha + grain, 0.0, 1.0);
  vec3 premultiplied = min(color, vec3(alpha));
  outColor = vec4((premultiplied + u[8].rgb * (1.0 - alpha)) * (1.0 - u[1].z), 1.0);
}

shaders.coarse:
#version 300 es
#define VIDEORC_PASS_COARSE
// Plasma Wave, from React Bits by David Haz (https://reactbits.dev, MIT +
// Commons Clause), used in Videorc with the author's permission. Adapted for
// Videorc (plan 190): the mouse heat and the intro are constants, dark mode
// only, float targets only (React Bits' range = 1), drawn opaque over the
// look's base colour, and uniforms are packed into `u` (layout in
// live_background/mod.rs).
//
// Passes (define one): VIDEORC_PASS_COARSE traces at a third of the fine size;
// VIDEORC_PASS_FINE re-traces only near edges, else samples the coarse trace
// (t0); VIDEORC_PASS_DOWN and VIDEORC_PASS_UP build the bloom chain (t0 the
// source, t1 the matching down level for UP); the default pass composites the
// fine light (t0) and the bloom (t1).
precision highp float;

uniform vec4 u[9];
uniform sampler2D t0;
uniform sampler2D t1;
out vec4 outColor;

const float PI = 3.14159265;
const float TAU = 6.28318531;
const float HALF_PI = 1.5707963;

#if defined(VIDEORC_PASS_COARSE) || defined(VIDEORC_PASS_FINE)
vec4 traceLight(vec2 pixel) {
  vec2 view = u[1].xy;
  vec2 coord = pixel - 0.5 * view;
  float c = cos(u[2].x);
  float sn = sin(u[2].x);
  coord = mat2(c, -sn, sn, c) * coord;
  vec3 dir = normalize(vec3(coord / view.y, u[2].y));
  vec3 o = vec3(0.0, 0.0, -7.0);
  float t = u[0].z * PI;
  float t1 = t * 0.7;
  float t2 = t * 0.9;
  float tSpeed1 = t * u[2].z;
  float tSpeed2 = t * u[2].w * u[3].x;
  float bend1 = u[3].y;
  float bend2 = u[3].z;
  float thickness = u[3].w;
  vec3 heat = u[7].xyz;
  float s = 1.0;
  float d = 0.0;
  vec2 k = vec2(0.0);
  for (int i = 0; i < 14; ++i) {
    vec3 p = o + dir * d;
    p.x -= 15.0;
    float px = p.x;
    float heatOffset = (px - heat.x) / heat.z;
    float swell = heat.y * exp(-heatOffset * heatOffset);
    float wob1 = bend1 + swell * (0.16 + 0.2 * bend1) + sin(t1 + px * 0.8) * 0.1;
    float wob2 = bend2 + swell * (0.16 + 0.2 * bend2) + cos(t2 + px * 1.1) * 0.1;
    vec2 a = sin(vec2(px, px + HALF_PI) + tSpeed1) * wob1;
    vec2 b = cos(vec2(px, px + HALF_PI) + tSpeed2) * wob2;
    float cut = px + thickness;
    k.x = max(cut, length(p.yz - a) - thickness);
    k.y = max(cut, length(p.yz - b) - thickness);
    s = min(s, min(k.x, k.y));
    if (s < 0.001 || d > 300.0) break;
    d += s * 0.7;
  }
  vec3 raw = max(cos(d * TAU) - s * sqrt(d) - vec3(k, 0.0), 0.0);
  float field = max(raw.r, max(raw.g, raw.b));
  raw.gb += 0.1;
  raw = raw * 0.4 + raw.brg * 0.6 + raw * raw;
  float lum = dot(raw, vec3(0.299, 0.587, 0.114));
  float w1 = max(0.0, 1.0 - k.x * 2.0) + 0.0001;
  float w2 = max(0.0, 1.0 - k.y * 2.0) + 0.0001;
  vec3 base = (u[5].rgb * w1 + u[6].rgb * w2) / (w1 + w2);
  float soft = smoothstep(0.03, 0.36, field);
  float hot = smoothstep(0.32, 0.8, field);
  vec3 light = base * lum * 2.6 * soft + mix(base, vec3(1.0), 0.55) * hot * u[4].x * 2.0;
  return vec4(light, field);
}
#endif

#if defined(VIDEORC_PASS_COARSE)
void main() {
  outColor = traceLight(gl_FragCoord.xy * (u[1].xy / u[0].xy));
}
#elif defined(VIDEORC_PASS_FINE)
void main() {
  vec2 coarseSize = vec2(textureSize(t0, 0));
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  vec2 pos = uv * coarseSize - 0.5;
  ivec2 cell = ivec2(floor(pos));
  ivec2 last = ivec2(coarseSize) - 1;
  float a = texelFetch(t0, clamp(cell, ivec2(0), last), 0).a;
  float b = texelFetch(t0, clamp(cell + ivec2(1, 0), ivec2(0), last), 0).a;
  float c = texelFetch(t0, clamp(cell + ivec2(0, 1), ivec2(0), last), 0).a;
  float d = texelFetch(t0, clamp(cell + ivec2(1, 1), ivec2(0), last), 0).a;
  float high = max(max(a, b), max(c, d));
  float low = min(min(a, b), min(c, d));
  if (high > 0.02 && low < 0.4) outColor = traceLight(gl_FragCoord.xy * (u[1].xy / u[0].xy));
  else outColor = texture(t0, uv);
}
#elif defined(VIDEORC_PASS_DOWN)
void main() {
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  vec2 texel = 1.0 / vec2(textureSize(t0, 0));
  vec4 sum = texture(t0, uv) * 4.0;
  sum += texture(t0, uv - texel);
  sum += texture(t0, uv + texel);
  sum += texture(t0, uv + vec2(texel.x, -texel.y));
  sum += texture(t0, uv - vec2(texel.x, -texel.y));
  outColor = sum / 8.0;
}
#elif defined(VIDEORC_PASS_UP)
void main() {
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  vec2 h = 0.5 / vec2(textureSize(t0, 0));
  vec4 sum = texture(t0, uv + vec2(-h.x * 2.0, 0.0));
  sum += texture(t0, uv + vec2(h.x * 2.0, 0.0));
  sum += texture(t0, uv + vec2(0.0, -h.y * 2.0));
  sum += texture(t0, uv + vec2(0.0, h.y * 2.0));
  sum += texture(t0, uv + vec2(-h.x, h.y)) * 2.0;
  sum += texture(t0, uv + h) * 2.0;
  sum += texture(t0, uv + vec2(h.x, -h.y)) * 2.0;
  sum += texture(t0, uv - h) * 2.0;
  outColor = sum / 12.0 + texture(t1, uv);
}
#else
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  float exposure = u[4].y;
  vec3 hdr = texture(t0, uv).rgb * exposure;
  hdr += texture(t1, uv).rgb * exposure * u[4].z * 0.18;
  float grain = (hash(gl_FragCoord.xy + fract(u[0].z * 7.31) * 113.0) - 0.5) * u[4].w;
  vec3 mapped = 1.0 - exp(-hdr);
  float level = max(mapped.r, max(mapped.g, mapped.b));
  mapped = clamp(mapped + grain * level, 0.0, 1.0) * u[5].w;
  float alpha = max(mapped.r, max(mapped.g, mapped.b));
  outColor = vec4((mapped + u[8].rgb * (1.0 - alpha)) * (1.0 - u[1].z), 1.0);
}
#endif

